import contract from "./fitgap-report.contract.json";
import type { FitGapReport, SkillComparison } from "@/types";

/**
 * The fit/gap report exactly as the API serialises it. Generated by
 * api/spec/contracts/fit_gap_report_contract_spec.rb from the real presenter,
 * so these tests fail if the two services drift apart.
 */
export const contractReport = contract as FitGapReport;

export function makeReport(overrides: Partial<FitGapReport> = {}): FitGapReport {
  return structuredClone({ ...contractReport, ...overrides });
}

export function row(label: string, overrides: Partial<SkillComparison> = {}): SkillComparison {
  const base = contractReport.skill_comparisons.find((c) => c.skill_label === label);
  if (!base) throw new Error(`No contract row for ${label}`);
  return { ...base, ...overrides };
}
